    private string OpenCodeFileProc(in string aFilename)
    {
        string l_Ext;
        TStream l_FS;
        string result;
    
        l_Ext = AnsiLowerCase(ExtractFileExt(aFilename));
        l_FS = gD2DE.Resource_CreateStream(aFilename, F2App.IsFromPack);
        if (l_FS != null)
        {
            try
            {
                if (l_Ext == ".qs2")
                {
                    result = FURQLoadQS2(l_FS);
                }
                else
                {
                    if (l_Ext == ".qs1")
                    {
                        result = FURQLoadQS1(l_FS);
                    }
                    else
                    {
                        result = FURQLoadQST(l_FS);
                    }
                }
            }
            finally
            {
                FreeAndNil(l_FS);
            }
        }
        else
        {
            OutError(Format("Файл %s не найден", new HashSet<int>(new int[] { (int)(ExtractFileName(aFilename)) })));
        }
        return result = default!;
    }
    
