    protected override void DoFrame(float aDelta)
    {
        Tf2BaseDecorator l_MouseDecorator;
    
        Context.Decorators.Update(aDelta);
        l_MouseDecorator = Context.GetMouseDecorator;
        gD2DE.HideMouse = (l_MouseDecorator != null);
        if (l_MouseDecorator != null)
        {
            l_MouseDecorator.PosX = gD2DE.MouseX;
            l_MouseDecorator.PosY = gD2DE.MouseY;
        }
        f_GUI.FrameFunc(aDelta);
        if ((f_Txt.State == tpsIdle) & (f_PauseTime > 0))
        {
            f_PauseTime = (f_PauseTime - aDelta);
            if (f_PauseTime <= 0)
            {
                f_PauseTime = 0;
                if (Context.State == csInputKey)
                {
                    Context.StateResult = "0";
                }
                else
                {
                    Context.StateResult = "";
                }
                NextTurn();
            }
        }
        if (f_WaitSprites[f_WaitState] != null)
        {
            if (f_WSWaitTimer <= 0)
            {
                f_WSAlpha = (f_WSAlpha + ((f_WSAlphaDir * cWaitSpriteAlphaSpeed) * aDelta));
                if (f_WSAlpha < cWaitSpriteAlphaMin)
                {
                    f_WSAlphaDir = 1;
                    f_WSAlpha = cWaitSpriteAlphaMin;
                }
                if (f_WSAlpha > cWaitSpriteAlphaMax)
                {
                    f_WSAlphaDir = ( - 1);
                    f_WSAlpha = cWaitSpriteAlphaMax;
                }
            }
            else
            {
                f_WSWaitTimer = (f_WSWaitTimer - aDelta);
            }
        }
    }
    
