    private void LoadMenuOnItem(Td2dMenuItem aRoot, string aItemName)
    {
        string l_ActName;
        bool l_IsDef;
        int I;
        Td2dMenuItem l_MI;
        string l_HideVariable;
        string l_NamePrefix;
        string l_CurUseItem;
    
        l_NamePrefix = (aItemName + "_");
        for (I = 0; I <= (Context.Code.ActionList.Count - 1); I++)
        {
            l_CurUseItem = Context.Code.ActionList[I];
            if (AnsiStartsText(l_NamePrefix, l_CurUseItem) | AnsiSameText(aItemName, l_CurUseItem))
            {
                l_HideVariable = ((SUsePrfix + l_CurUseItem) + SHideSuffix);
                if (Context.Variables[l_HideVariable] == 0)
                {
                    l_ActName = Trim(Copy(l_CurUseItem, (Length(l_NamePrefix) + 1), MaxInt));
                    l_IsDef = (l_ActName == "");
                    if (l_IsDef)
                    {
                        l_ActName = sDefaultActName;
                    }
                    l_MI = Td2dMenuItem.Create(l_ActName);
                    l_MI.Tag = Context.Code.ActionList.Variants[I];
                    l_MI.OnClick = InvMenuHandler;
                    aRoot.AddChild(l_MI);
                }
            }
        }
    }
    
    private void LogAddTextHandler(in TObject aSender, in string aText, uint aColor, Td2dTextAlignType aParaType)
    {
        TFileStream l_F;
        ushort l_Mode;
    
        if (aText == "")
        {
            return;
        }
        if (FileExists(f_LogFileName))
        {
            l_Mode = fmOpenReadWrite;
        }
        else
        {
            l_Mode = fmCreate;
        }
        l_F = TFileStream.Create(f_LogFileName, l_Mode);
        try
        {
            l_F.Seek(0, soFromEnd);
            l_F.Write(aText[1], Length(aText));
        }
        finally
        {
            global::FireURQ.Runtime.TObject.Free(l_F);
        }
    }
    
