    private void NextTurn()
    {
        bool l_ActionsAllowed;
    
        f_Txt.ClearButtons();
        f_Txt.FixMorePosition();
        f_ActionMenu.Close();
        f_PauseTime = 0;
        f_Interpreter.Execute(Context);
        CheckWaitState();
        l_ActionsAllowed = !((Context.State == csInput) || (Context.State == csInputKey));
        f_Txt.LinksAllowed = l_ActionsAllowed;
        Context.AllowActionDecorators(l_ActionsAllowed);
        switch (Context.State)
        {
            case csEnd:
                DoEnd();
                break;
            case csSave:
                SaveGame();
                break;
            case csInput:
                HandleInput();
                break;
            case csInputKey:
                HandleInputKey();
                break;
            case csPause:
                DoPause();
                break;
            case csLoad:
                LoadGame();
                break;
            case csQuit:
                DoQuit();
                break;
        }
    }
    
