    private void pm_SetWaitState(in Tf2WaitState Value)
    {
        if (Value != f_WaitState)
        {
            switch (Value)
            {
                case wsTimer:
                    if (Context.Variables[SVarHidePauseIndicator] > 0)
                    {
                        f_WaitState = wsNone;
                        return;
                    }
                    break;
                case wsAnykey:
                    if (Context.Variables[SVarHideAnykeyIndicator] > 0)
                    {
                        f_WaitState = wsNone;
                        return;
                    }
                    break;
                case wsScroll:
                    if (Context.Variables[SVarHideMoreIndicator] > 0)
                    {
                        f_WaitState = wsNone;
                        return;
                    }
                    break;
            }
            f_WaitState = Value;
            f_WSAlpha = cWaitSpriteAlphaMin;
            f_WSAlphaDir = 1;
            f_WSWaitTimer = cTimeBeforeWaitSprite;
        }
    }
    
    protected override void DoProcessEvent(ref Td2dInputEvent theEvent)
    {
        If2ActionDecorator l_AD;
        Tf2BaseDecorator l_Decor;
        int l_Idx;
        Tf2BaseDecorator l_MouseDecorator;
        Td2dControl l_TopCtrl;
    
        try
        {
            if ((f_Txt.State == tpsIdle) & (theEvent.EventType == INPUT_KEYDOWN))
            {
                if ((theEvent.KeyCode == D2DK_C) & (theEvent.Flags & (D2DINP_CTRL != 0)))
                {
                    CopyToClipboard();
                    Processed(theEvent);
                }
                else
                {
                    if ((Context.State == csInputKey) & ~D2DIsAnyOpenMenu(f_GUI))
                    {
                        if ((theEvent.KeyChar == 0) & !cNonProcessedKeys.Contains((int)(theEvent.KeyCode)))
                        {
                            theEvent.KeyChar = theEvent.KeyScan;
                            Context.Variables[SVarIsSyskey] = 1.0;
                        }
                        else
                        {
                            Context.Variables[SVarIsSyskey] = 0.0;
                        }
                        if (theEvent.KeyChar != 0)
                        {
                            Context.StateResult = IntToStr(theEvent.KeyChar);
                            NextTurn();
                        }
                        Processed(theEvent);
                    }
                }
                if ((F2App.DebugMode & (theEvent.KeyCode == D2DK_R)) & (theEvent.Flags & (D2DINP_CTRL != 0)))
                {
                    DoDebugReload();
                }
            }
            if (theEvent.EventType == INPUT_KEYDOWN)
            {
                if ((theEvent.KeyCode == D2DK_ENTER) & (theEvent.Flags & (D2DINP_ALT > 0)))
                {
                    if (f_Context.Variables[SAltEnterDisable] == 0)
                    {
                        if (f_Context.Variables[SFullscreen] > 0)
                        {
                            f_Context.Variables[SFullscreen] = 0;
                        }
                        else
                        {
                            f_Context.Variables[SFullscreen] = 1;
                        }
                    }
                    Processed(theEvent);
                }
            }
            l_TopCtrl = f_GUI.TopmostVisible;
            if ((l_TopCtrl != null) & (l_TopCtrl is Td2dMenu))
            {
                l_TopCtrl.ProcessEvent(theEvent);
            }
            l_MouseDecorator = Context.GetMouseDecorator;
            l_Idx = (Context.Decorators.Count - 1);
            while ((l_Idx >= 0) & (Context.Decorators.Decorators[l_Idx].PosZ < 0))
            {
                l_Decor = Context.Decorators.Decorators[l_Idx];
                if (l_Decor != l_MouseDecorator)
                {
                    l_AD = l_Decor.AsActionDecorator;
                    if ((l_AD != null) & l_Decor.Visible)
                    {
                        l_AD.ProcessEvent(theEvent);
                        if (IsProcessed(theEvent))
                        {
                            break;
                        }
                    }
                }
                Dec(l_Idx);
            }
            if (~IsProcessed(theEvent))
            {
                f_GUI.ProcessEvent(theEvent);
            }
            if (~IsProcessed(theEvent))
            {
                if (l_Idx >= Context.Decorators.Count)
                {
                    l_Idx = (Context.Decorators.Count - 1);
                }
                while (l_Idx >= 0)
                {
                    l_Decor = Context.Decorators.Decorators[l_Idx];
                    if (l_Decor != l_MouseDecorator)
                    {
                        l_AD = l_Decor.AsActionDecorator;
                        if ((l_AD != null) & l_Decor.Visible)
                        {
                            l_AD.ProcessEvent(theEvent);
                            if (IsProcessed(theEvent))
                            {
                                break;
                            }
                        }
                    }
                    Dec(l_Idx);
                }
            }
            if (theEvent.EventType == INPUT_KEYDOWN)
            {
                if (((theEvent.KeyCode == D2DK_I) & !f_InvMenu.Visible) & InvMenuEnabled)
                {
                    OpenInvMenu();
                    Processed(theEvent);
                }
                if (((theEvent.KeyCode == D2DK_ESCAPE) & !f_SysMenu.Visible) & SysMenuEnabled)
                {
                    if (f_Context.Variables[SEscapeDisable] == 0)
                    {
                        OpenSysMenu();
                    }
                    Processed(theEvent);
                }
            }
            if (((theEvent.EventType == INPUT_MBUTTONDOWN) & (Context.State == csInputKey)) & (f_Txt.State == tpsIdle))
            {
                switch (theEvent.KeyCode)
                {
                    case D2DK_LBUTTON:
                        Context.StateResult = "256";
                        break;
                    case D2DK_RBUTTON:
                        Context.StateResult = "257";
                        break;
                    case D2DK_MBUTTON:
                        Context.StateResult = "258";
                        break;
                }
                Processed(theEvent);
                NextTurn();
            }
        }
        catch (Exception)
        {
            OutError(E.Message);
        }
    }
    
