    private void ReloadInventory()
    {
        int l_Idx;
        Td2dMenuItem l_MI;
        bool l_InvIsOpen;
    
        l_InvIsOpen = f_InvMenu.Visible;
        ClearInventory();
        LoadMenuOnItem(f_InvMenu.Root, SInv);
        for (l_Idx = 0; l_Idx <= Context.Inventory.LastIndex; l_Idx++)
        {
            l_MI = Td2dMenuItem.Create(Context.GetInventoryString(l_Idx));
            LoadMenuOnItem(l_MI, Context.Inventory.Strings[l_Idx]);
            if ((l_MI.ChildrenCount == 1) & (l_MI.pm_GetChildren(0).Caption == sDefaultActName))
            {
                l_MI.OnClick = l_MI.pm_GetChildren(0).OnClick;
                l_MI.Tag = l_MI.pm_GetChildren(0).Tag;
                l_MI.ClearChildren();
            }
            f_InvMenu.Root.AddChild(l_MI);
        }
        InvEnable();
        if (InvMenuEnabled && l_InvIsOpen)
        {
            InvPopup();
        }
    }
    
    protected override void DoRender()
    {
        uint l_Color;
        int l_DIdx;
        Td2dControl l_TopCtrl;
        int I;
        Tf2BaseDecorator l_MouseDecorator;
        Tf2BaseDecorator l_Decorator;
        Tf2DecorationSprite l_SkinDecorator;
        int l_DSIdx;
        Tf2BaseDecorator l_GetDecorator(bool IsBeforeZero)
        {
            Tf2BaseDecorator __localResult1;
            if (l_DIdx < Context.Decorators.Count)
            {
                __localResult1 = Context.Decorators.Decorators[l_DIdx];
                if (IsBeforeZero && (__localResult1.PosZ < 0))
                {
                    __localResult1 = null;
                }
            }
            else
            {
                __localResult1 = null;
            }
            return __localResult1;
        }
    
        Tf2DecorationSprite l_GetSkinDecorator(bool IsBeforeZero)
        {
            Tf2DecorationSprite __localResult1;
            if (f_SkinDecorList != null)
            {
                if (l_DSIdx < f_SkinDecorList.Count)
                {
                    __localResult1 = ((Tf2DecorationSprite)(f_SkinDecorList.Items[l_DSIdx]));
                    if (IsBeforeZero && (__localResult1.Z < 0))
                    {
                        __localResult1 = null;
                    }
                }
                else
                {
                    __localResult1 = null;
                }
            }
            else
            {
                __localResult1 = null;
            }
            return __localResult1;
        }
    
        void l_CheckIfMouseDecorator(bool IsBeforeZero)
        {
            if ((l_Decorator != null) & (l_Decorator == l_MouseDecorator))
            {
                l_DIdx++;
                l_Decorator = l_GetDecorator(IsBeforeZero);
            }
        }
    
        void l_UseDecorator(bool IsBeforeZero)
        {
            l_Decorator.Render();
            l_DIdx++;
            l_Decorator = l_GetDecorator(IsBeforeZero);
            l_CheckIfMouseDecorator(IsBeforeZero);
        }
    
        void l_UseSkinDecorator(bool IsBeforeZero)
        {
            l_SkinDecorator.Render();
            l_DSIdx++;
            l_SkinDecorator = l_GetSkinDecorator(IsBeforeZero);
        }
    
        void l_RenderDecorators(bool IsBeforeZero)
        {
            l_Decorator = l_GetDecorator(IsBeforeZero);
            l_CheckIfMouseDecorator(IsBeforeZero);
            l_SkinDecorator = l_GetSkinDecorator(IsBeforeZero);
            while ((l_Decorator != null) | (l_SkinDecorator != null))
            {
                if (l_Decorator != null)
                {
                    if (l_SkinDecorator != null)
                    {
                        if (l_Decorator.PosZ > l_SkinDecorator.Z)
                        {
                            l_UseDecorator(IsBeforeZero);
                        }
                        else
                        {
                            l_UseSkinDecorator(IsBeforeZero);
                        }
                    }
                    else
                    {
                        l_UseDecorator(IsBeforeZero);
                    }
                }
                else
                {
                    l_UseSkinDecorator(IsBeforeZero);
                }
            }
        }
    
    
        gD2DE.Gfx_Clear(f_BGColor);
        l_DIdx = 0;
        l_DSIdx = 0;
        l_MouseDecorator = Context.GetMouseDecorator;
        gD2DE.HideMouse = (l_MouseDecorator != null);
        l_RenderDecorators(true);
        f_GUI.Render();
        if ((f_WaitSprites[f_WaitState] != null) & (f_WSWaitTimer <= 0))
        {
            l_Color = ((Trunc(f_WSAlpha) << 24) | 0xFFFFFF);
            f_WaitSprites[f_WaitState].SetColor(l_Color);
            f_WaitSprites[f_WaitState].Render((f_Txt.X + (f_Txt.Width - 33)), (f_Txt.Y + (f_Txt.Height - 33)));
        }
        l_RenderDecorators(false);
        l_TopCtrl = f_GUI.TopmostVisible;
        if ((l_TopCtrl != null) & (l_TopCtrl is Td2dMenu))
        {
            l_TopCtrl.Render();
        }
        if ((l_MouseDecorator != null) & !HasRunningChild)
        {
            l_MouseDecorator.Render();
        }
    }
    
    private void LinkClickHandler(in TObject aSender, in Td2dRect aRect, in string aTarget)
    {
        string l_LinkText;
    
        if (aTarget != "")
        {
            l_LinkText = f_Txt.GetHighlightedLinkText;
            if (Context.ActionIsMenu(aTarget))
            {
                f_MenuActionCaller = l_LinkText;
                f_MenuActionCallerID = ciLink;
                PopupActionMenu(aTarget, aRect, Context.LinkMenuAlign);
            }
            else
            {
                Context.StateResult = Format("b:%s", new HashSet<int>(new int[] { (int)(aTarget) }));
                Context.Variables["last_btn_caption"] = l_LinkText;
                f_Txt.ClearButtons();
                if ((global::furqTypesModule.EnsureReal(Context.Variables[c_HideLinkEchoVar]) == 0.0) & (Context.ActionIsFinal(aTarget) | (global::furqTypesModule.EnsureReal(Context.Variables[c_HideLocalActionEchoVar]) == 0.0)))
                {
                    ActionMessage(l_LinkText);
                }
                NextTurn();
            }
        }
    }
    
    private void LoadGame()
    {
        Context();
    }
    
    public void LoadSavegameNames()
    {
        int I;
        string l_Caption = default!;
        double l_DT = default!;
    
        f_SaveLoadManager.SetSaveBase(Context);
        for (I = 0; I <= cMaxSlotsNum; I++)
        {
            f_SaveLoadManager.GetSaveInfo(I, l_Caption, l_DT);
            f_SaveLoadScene.Captions[I] = l_Caption;
            f_SaveLoadScene.DT[I] = l_DT;
        }
    }
    
    private void miaLog(TObject aSender)
    {
        if (f_Txt.OnAddText != null)
        {
            StopLogging();
        }
        else
        {
            StartLogging();
        }
    }
    
    public void miaReload(TObject aSender)
    {
        DoDebugReload();
    }
    
    private void PopupActionMenu(in string aActionID, Td2dRect aRect, Td2dAlign aAlign)
    {
        f_ActionMenu.Root.ClearChildren();
        f_KeepMenuActions = false;
        BuildMenuFromAction(aActionID, f_ActionMenu.Root);
        if (f_ActionMenu.Root.ChildrenCount > 0)
        {
            f_ActionMenu.Font = Context.MenuFont;
            f_ActionMenu.VisulalStyle = Context.MenuVisualStyle;
            f_ActionMenu.Popup(aRect, aAlign);
        }
    }
    
    private void RunTimeErrorHandler(in string aErrorMessage, int aLine)
    {
        string l_ErrMsg;
    
        l_ErrMsg = Format("ОШИБКА: \"%s\" в %s", new HashSet<int>(new int[] { (int)(aErrorMessage), (int)(f_Code.GetSourcePointStr((aLine - 1))) }));
        gD2DE.System_Log(l_ErrMsg);
        if (F2App.DebugMode)
        {
            f_Txt.AddText(Format("\r\n%s\r\n\r\n", new HashSet<int>(new int[] { (int)(l_ErrMsg) })), f_SysTextFont, 0xFFFF4800, ptLeftAligned);
        }
    }
    
    private void SaveGame()
    {
        int l_SlotNo;
    
        Context();
    }
    
    private void StartLogging(bool aDisplay)
    {
        string l_Name;
    
        f_LogFileName = GetLogFilename;
        f_mi_Log.Caption = SStopLog;
        if (aDisplay)
        {
            l_Name = ExtractFileName(f_LogFileName);
            f_Txt.ClearButtons();
            ActionMessage(("Запись лога в файл " + l_Name));
            LoadButtonsAndActions();
            f_Txt.ScrollToBottom();
        }
        f_Txt.OnAddText = LogAddTextHandler;
    }
    
    private void StartOver(bool aNeedClearTextPane)
    {
        FreeAndNil(f_Context);
        Context = Tf2Context.Create(f_Code, f_CurFilename, f_SysTextFont, f_MenuFont, f_SysMenu.VisulalStyle, f_Txt, F2App.Skin, f_BFrame, F2App.SavePath);
        Context.SettingsStorage = F2App.SettingsStorage;
        Context.OnDecoratorAction = DecoratorActionHandler;
        f_mi_Restart.Enabled = true;
        f_mi_Load.Enabled = true;
        gD2DE.Music_Stop();
        gD2DE.Snd_FreeAll();
        gD2DE.Texture_ClearCache();
        ClearInventory();
        if (aNeedClearTextPane)
        {
            ClearTextPane();
        }
    }
    
    private void StopLogging()
    {
        f_Txt.OnAddText = null;
        f_mi_Log.Caption = SStartLog;
        f_Txt.ClearButtons();
        ActionMessage("Запись лога остановлена");
        LoadButtonsAndActions();
        f_Txt.ScrollToBottom();
    }
    
}

